public String reverseWords(String s) {
    char[] a = s.toCharArray();
    int n = a.length;
    reverse(a, 0, n - 1);        // 1. reverse the whole string
    reverseEachWord(a, n);        // 2. reverse each word back
    return cleanSpaces(a, n);     // 3. trim + collapse spaces
}

private void reverse(char[] a, int left, int right) {
    while (left < right) {
        char tmp = a[left];
        a[left++] = a[right];
        a[right--] = tmp;
    }
}

private void reverseEachWord(char[] a, int n) {
    int start = 0, end = 0;
    while (start < n) {
        while (start < end || (start < n && a[start] == ' ')) start++;  // skip spaces
        while (end < start || (end < n && a[end] != ' ')) end++;        // reach word end
        reverse(a, start, end - 1);                                     // reverse the word
    }
}

private String cleanSpaces(char[] a, int n) {
    int i = 0, j = 0;
    while (j < n) {
        while (j < n && a[j] == ' ') j++;             // skip leading spaces
        while (j < n && a[j] != ' ') a[i++] = a[j++]; // copy a word
        while (j < n && a[j] == ' ') j++;             // skip spaces after the word
        if (j < n) a[i++] = ' ';                      // single separator before next word
    }
    return new String(a, 0, i);
}

code.python:
def reverseWords(self, s: str) -> str:
    a = list(s)
    n = len(a)
    self.reverse(a, 0, n - 1)        # 1. reverse the whole string
    self.reverse_each_word(a, n)      # 2. reverse each word back
    return self.clean_spaces(a, n)    # 3. trim + collapse spaces

def reverse(self, a: list[str], left: int, right: int) -> None:
    while left < right:
        a[left], a[right] = a[right], a[left]
        left += 1
        right -= 1

def reverse_each_word(self, a: list[str], n: int) -> None:
    start = end = 0
    while start < n:
        while start < end or (start < n and a[start] == " "):
            start += 1
        while end < start or (end < n and a[end] != " "):
            end += 1
        self.reverse(a, start, end - 1)

def clean_spaces(self, a: list[str], n: int) -> str:
    i = j = 0
    while j < n:
        while j < n and a[j] == " ":
            j += 1
        while j < n and a[j] != " ":
            a[i] = a[j]
            i += 1
            j += 1
        while j < n and a[j] == " ":
            j += 1
        if j < n:
            a[i] = " "
            i += 1
    return "".join(a[:i])

